"""Seating chart text for a class."""

from rosterkit.errors import ProjectError


def seating_rows(*, students, seats_per_row):
    """Return one 'Row N: Last, First | ...' line per row, sorted by last name."""
    if seats_per_row <= 0:
        raise ProjectError('seats_per_row must be positive')
    if not students:
        raise ProjectError('no students to seat')
    ordered = sorted(students, key=lambda s: (s.last_name, s.first_name))
    result = []
    for start in range(0, len(ordered), seats_per_row):
        names = ' | '.join(s.display_name for s in ordered[start:start + seats_per_row])
        result.append(f'Row {start // seats_per_row + 1}: {names}')
    return result
EOF
mkdir qa && cat > qa/test_seating.py <<'EOF'
import unittest

from rosterkit.errors import ProjectError
from rosterkit.models import Student
from rosterkit.seating import seating_rows


def _student(last, first):
    return Student(student_id=last, last_name=last, first_name=first, section='A')


class SeatingTests(unittest.TestCase):
    def test_when_students_given_rows_are_sorted_and_split(self):
        students = [_student('Halloway', 'Juno'), _student('Zed', 'Al'), _student('Dunmere', 'Piet')]
        self.assertEqual(
            seating_rows(students=students, seats_per_row=2),
            ['Row 1: Dunmere, Piet | Halloway, Juno', 'Row 2: Zed, Al'],
        )

    def test_when_seats_not_positive_error_is_raised(self):
        for seats in (0, -1):
            with self.assertRaises(ProjectError):
                seating_rows(students=[_student('A', 'B')], seats_per_row=seats)

    def test_when_no_students_error_is_raised(self):
        with self.assertRaises(ProjectError):
            seating_rows(students=[], seats_per_row=2)
EOF
